SET LOCAL aidash.scope = 'deployment';
WITH updated_bundles AS (
UPDATE "authorization_bundles" SET "document" = (regexp_replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(replace(document::text, '"thread.create"', '"workspace.create"'), '"thread.events"', '"workspace.events"'), '"thread.read"', '"workspace.read"'), '"thread.share"', '"workspace.share"'), '"thread.update"', '"workspace.update"'), '"thread_id"', '"workspace_id"'), '"/thread_id"', '"/workspace_id"'), '"thread"', '"workspace"'), '"source_thread_id"', '"source_workspace_id"'), '"/source_thread_id"', '"/source_workspace_id"'), '("aidash://[^"/]+/[^"/]+)/threads/', '\1/workspaces/', 'g'))::jsonb, "revision" = "revision" + 1, "updated_at" = CURRENT_TIMESTAMP WHERE (document::text LIKE '%"thread.create"%' OR document::text LIKE '%"thread.events"%' OR document::text LIKE '%"thread.read"%' OR document::text LIKE '%"thread.share"%' OR document::text LIKE '%"thread.update"%' OR document::text LIKE '%"thread_id"%' OR document::text LIKE '%"/thread_id"%' OR document::text LIKE '%"thread"%' OR document::text LIKE '%"source_thread_id"%' OR document::text LIKE '%"/source_thread_id"%' OR document::text ~ '("aidash://[^"/]+/[^"/]+)/threads/') RETURNING "tenant", "revision", "document"
)
INSERT INTO "authorization_revisions" ("tenant", "revision", "document", "actor") SELECT "tenant", "revision", "document", 'migration:identity/0111_thread_member_policy' FROM "updated_bundles";
